const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const titles={dashboard:'Farm overview',farms:'My farms',recommend:'Crop recommendation',diagnose:'Crop health check',weather:'Weather update',market:'Market prices',assistant:'AI farming assistant',planner:'Operations planner',decision:'Autonomous farm decision engine',impact:'Water & profit',fieldmap:'Field health map',shops:'Nearby agricultural shops',recovery:'Crop recovery tracker',soilhealth:'Soil health advisor',yieldrisk:'Yield & risk simulator',calendar:'Smart farm calendar',schemes:'Government schemes & expert help'};
const crops=['Wheat','Rice','Mustard','Maize','Chickpea','Cotton','Tomato'];
const prices=[['Wheat',2550,'Stable'],['Rice / Paddy',2320,'Rising'],['Mustard',6100,'Stable'],['Maize',2250,'Falling'],['Chickpea',5600,'Stable'],['Cotton',7200,'Rising'],['Tomato',1800,'Volatile']];
const seed=[{id:1,name:'Demo Farm',location:'Demo Village, Sonipat, Haryana',village:'Demo Village',district:'Sonipat',state:'Haryana',crop:'Wheat',area_acres:4,soil_type:'Loamy',soil_ph:6.7,moisture:'medium',land_status:'owner',farmer_category:'small-marginal',irrigation:'tubewell',scheme_need:'general'}];
let farms=read('agri-farms',seed), activities=read('agri-activities',[]), currentWeather=null;
function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function save(){localStorage.setItem('agri-farms',JSON.stringify(farms));localStorage.setItem('agri-activities',JSON.stringify(activities))}
async function backendPost(path,payload){try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('API '+r.status);return await r.json()}catch(err){console.info('Backend not connected; browser-local copy retained.',err.message);return null}}
async function backendPut(path,payload){try{const r=await fetch(path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('API '+r.status);return await r.json()}catch(err){console.info('Backend sync unavailable; browser-local copy retained.',err.message);return null}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function go(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===view));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-title').textContent=titles[view]||'Farm overview';window.scrollTo({top:0,behavior:'smooth'});if(view==='farms')loadFarms();if(view==='weather')loadWeather();if(view==='market')loadMarket();if(view==='planner'){plannerFarmList();loadActivity()}}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));
$$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
$('#today').textContent=new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date());
function formObject(form){return Object.fromEntries(new FormData(form).entries())}
function farmLocation(f){return [f.village, f.district, f.state].filter(Boolean).join(', ') || f.location || 'Location not entered'}
function loadFarms(){farms=read('agri-farms',seed);$('#farm-count').textContent=farms.length;$('#farms-list').innerHTML=farms.map(f=>`<div class="farm-card"><div class="farm-card-icon">♧</div><div class="farm-card-main"><b>${esc(f.name)}</b><small>⌖ ${esc(farmLocation(f))}</small><div class="farm-meta"><span>${esc(f.crop)}</span><span>${esc(f.area_acres)} acres</span><span>pH ${esc(f.soil_ph ?? 'not entered')}</span></div><button class="text-btn farm-open-plan" type="button" data-farm-plan-id="${esc(f.id)}">View personalized plan →</button></div><span class="moisture ${f.moisture==='high'?'wet':f.moisture==='low'?'dry':''}">${f.moisture==='high'?'Wet':f.moisture==='low'?'Dry':'Normal'}</span></div>`).join('')||'<div class="empty-state">No farms added yet.</div>';const selector=$('#farm-plan-select');if(selector){const old=selector.value;selector.innerHTML=farms.map(f=>`<option value="${esc(f.id)}">${esc(f.name)} — ${esc(farmLocation(f))}</option>`).join('');if(farms.some(f=>String(f.id)===old))selector.value=old;}renderFarmPersonalPlan();plannerFarmList();renderDashboardTasks()}
$('#farm-form').addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget);d.location=[d.village,d.district,d.state].filter(Boolean).join(', ');const farm={...d,id:Date.now(),area_acres:Number(d.area_acres||1),soil_ph:d.soil_ph===''?null:Number(d.soil_ph)};farms.push(farm);save();backendPost('/api/farms',farm);e.currentTarget.reset();$('#farm-message').textContent='Farm saved on this device'+(location.protocol==='http:'?' and synced to the local backend when available':'. Run with npm start to enable backend sync.');toast('Farm saved and plan updated');loadFarms();$('#farm-plan-select').value=String(farm.id);renderFarmPersonalPlan()});
const cropInfo=[
{crop:'Wheat',season:['Rabi'],soil:['Loamy','Clay loam'],water:'medium',min:6,max:7.5,temp:[10,25],duration:'medium',cost:[12000,26000],waterLabel:'Medium',note:'Cool-season cereal; avoid waterlogging and check sowing window.',nutrient:'balanced'},
{crop:'Rice',season:['Kharif'],soil:['Clay','Clay loam'],water:'high',min:5.5,max:7,temp:[20,35],duration:'long',cost:[18000,40000],waterLabel:'High',note:'Needs reliable water and suitable drainage/field levelling; not ideal with limited water.',nutrient:'high'},
{crop:'Mustard',season:['Rabi'],soil:['Sandy loam','Loamy'],water:'low',min:6,max:7.5,temp:[10,25],duration:'medium',cost:[8000,18000],waterLabel:'Low',note:'Often a lower-water option; avoid excessive irrigation during flowering.',nutrient:'low'},
{crop:'Maize',season:['Kharif','Spring','Summer'],soil:['Loamy','Sandy loam'],water:'medium',min:5.5,max:7.5,temp:[18,32],duration:'medium',cost:[10000,24000],waterLabel:'Medium',note:'Needs moisture around flowering and well-drained soil.',nutrient:'high'},
{crop:'Chickpea',season:['Rabi'],soil:['Loamy','Sandy loam'],water:'low',min:6,max:8,temp:[10,30],duration:'medium',cost:[7000,16000],waterLabel:'Low',note:'Prefers well-drained soil; waterlogging can harm roots.',nutrient:'low'},
{crop:'Cotton',season:['Kharif'],soil:['Black soil','Loamy'],water:'medium',min:5.8,max:8,temp:[21,35],duration:'long',cost:[18000,42000],waterLabel:'Medium',note:'Long-duration crop; needs regular pest scouting and a suitable local variety.',nutrient:'high'},
{crop:'Tomato',season:['Rabi','Kharif','Spring','Summer'],soil:['Loamy','Sandy loam'],water:'medium',min:5.5,max:7,temp:[18,30],duration:'medium',cost:[25000,70000],waterLabel:'Medium',note:'Higher management and market-price risk; use staking/irrigation suited to local practice.',nutrient:'high'},
{crop:'Potato',season:['Rabi'],soil:['Sandy loam','Loamy'],water:'medium',min:5, max:6.5,temp:[12,25],duration:'short',cost:[25000,60000],waterLabel:'Medium',note:'Needs suitable cool conditions, quality seed tubers and careful disease management.',nutrient:'high'},
{crop:'Sugarcane',season:['Kharif','Spring','Summer'],soil:['Loamy','Clay loam'],water:'high',min:6,max:8,temp:[20,35],duration:'long',cost:[35000,80000],waterLabel:'High',note:'Long-duration, water-demanding crop; confirm local mill/buyer access first.',nutrient:'high'}
];
const cropCostFmt=n=>'₹'+Number(n).toLocaleString('en-IN');
$('#recommend-form').addEventListener('submit',e=>{
  e.preventDefault();
  const d=formObject(e.currentTarget),ph=Number(d.soil_ph),temp=Number(d.temperature),area=Number(d.area),budget=Number(d.budget);
  if(!e.currentTarget.reportValidity())return;
  if(!Number.isFinite(ph)||ph<0||ph>14||!Number.isFinite(temp)||temp< -10||temp>60||area<=0||budget<0){toast('Please check the entered values');return}
  const season=d.season, soil=d.soil_type, water=d.water;
  const scored=cropInfo.map(c=>{
    let score=50, reasons=[], cautions=[];
    if(c.season.includes(season)||season==='Year-round / unsure'){score+=12;reasons.push('season is broadly compatible')}else{score-=14;cautions.push('season timing may not fit')}
    if(ph>=c.min&&ph<=c.max){score+=12;reasons.push('pH is within the crop’s broad range')}else{score-=Math.min(14,Math.abs(ph<(c.min)?c.min-ph:ph-c.max)*5);cautions.push('pH may need local soil-test review')}
    if(c.soil.includes(soil)||(soil==='Sandy'&&c.soil.includes('Sandy loam'))){score+=9;reasons.push('soil type is a broad match')}else if(soil==='Clay'&&c.soil.includes('Clay loam')){score+=3;cautions.push('drainage needs checking')}else{score-=4;cautions.push('soil texture is not the strongest match')}
    if(water===c.water){score+=9;reasons.push('water demand aligns with availability')}else if(water==='low'&&c.water==='high'){score-=20;cautions.push('water demand may exceed supply')}else if(water==='medium'&&c.water==='high'){score-=8;cautions.push('reliable irrigation is important')}else if(water==='high'&&c.water==='low'){score+=1}
    if(temp>=c.temp[0]&&temp<=c.temp[1]){score+=7;reasons.push('entered temperature is broadly suitable')}else{score-=6;cautions.push('temperature may be outside the broad preferred range')}
    if(d.duration==='any'||d.duration===c.duration){score+=5;reasons.push('duration matches your preference')}else{score-=4;cautions.push('crop duration differs from preference')}
    if(d.goal==='low-cost'){if(c.cost[1]<=20000){score+=7;reasons.push('estimated input cost is relatively lower')}else{score-=7;cautions.push('estimated input cost may exceed a low-cost goal')}}
    if(d.goal==='water-saving'){if(c.water==='low'){score+=10;reasons.push('relatively lower water demand')}else if(c.water==='high'){score-=12;cautions.push('not a water-saving option')}}
    if(d.goal==='quick'){if(c.duration==='short'){score+=10;reasons.push('shorter crop duration')}else if(c.duration==='long'){score-=9;cautions.push('long growing period')}}
    if(d.goal==='market'){if(d.market_access==='limited'&&['Tomato','Potato','Cotton','Sugarcane'].includes(c.crop)){score-=6;cautions.push('check buyer/storage/transport before choosing')}else{score+=3;reasons.push('market planning should be checked locally')}}
    if(d.rainfall==='high'&&c.water==='high'){score+=2}else if(d.rainfall==='low'&&c.water==='high'){score-=7;cautions.push('dry outlook may increase irrigation needs')}
    if(d.moisture==='high'&&['Rice','Sugarcane'].includes(c.crop)){score+=2}else if(d.moisture==='high'){score-=5;cautions.push('check drainage before sowing')}
    if(d.moisture==='low'&&c.water==='low'){score+=3;reasons.push('lower water demand may suit dry conditions')}
    if(d.nitrogen==='low'&&c.nutrient==='high'){score-=3;cautions.push('nutrient planning is important; confirm with soil test')}
    if(d.concern==='waterlogging'&&['Chickpea','Mustard','Maize'].includes(c.crop)){score-=5;cautions.push('improve drainage / inspect field first')}
    if(d.concern==='drought'&&c.water==='high'){score-=12;cautions.push('high water demand during drought risk')}
    if(d.concern==='salinity'){score-=3;cautions.push('test soil salinity/EC before crop selection')}
    if(d.concern==='pests'&&['Cotton','Tomato','Potato'].includes(c.crop)){score-=3;cautions.push('plan frequent pest scouting')}
    if(d.previous_crop===c.crop){score-=4;cautions.push('avoid repeating the same crop without rotation advice')}
    const lowTotal=c.cost[0]*area,highTotal=c.cost[1]*area;
    if(budget<lowTotal){score-=12;cautions.push(`estimated input budget starts near ${cropCostFmt(lowTotal)} for this area`)}else if(budget>=highTotal){score+=3;reasons.push('budget covers the broad estimated input range')}
    return {...c,score:Math.max(20,Math.min(95,Math.round(score))),reasons,cautions,lowTotal,highTotal};
  }).sort((a,b)=>b.score-a.score).slice(0,5);
  const loc=[d.village,d.district,d.state].join(', ');
  const cards=scored.map((r,i)=>`<article class="recommend-card shortlist-card"><div class="rank">${String(i+1).padStart(2,'0')}</div><div class="recommend-main"><div class="recommend-title"><b>${esc(r.crop)}</b><span class="score">Fit score ${r.score}/100</span></div><div class="chip-row"><span>${esc(r.season.join(' / '))}</span><span>${esc(r.waterLabel)} water</span><span>${esc(r.duration)} duration</span><span>pH ${r.min}–${r.max}</span></div><p>${esc(r.note)}</p><div class="shortlist-facts"><div><small>Estimated input cost for ${area} acre(s)</small><b>${cropCostFmt(r.lowTotal)}–${cropCostFmt(r.highTotal)}</b></div><div><small>Broad temperature range</small><b>${r.temp[0]}–${r.temp[1]}°C</b></div></div><details><summary>Why this crop ranked here</summary><ul>${r.reasons.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Limited matching factors found.</li>'}</ul>${r.cautions.length?`<b>Check before choosing</b><ul>${r.cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</details><a class="outline-btn shortlist-map-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(r.crop+' seeds agricultural market '+loc)}">Explore local ${esc(r.crop)} seed/market results ↗</a></div></article>`).join('');
  const html=`<div class="shortlist-summary"><span class="welcome-kicker">YOUR FARM PROFILE</span><h4>${esc(loc)}</h4><div class="farm-meta"><span>${area} acres</span><span>${esc(soil)} soil</span><span>${esc(season)}</span><span>Budget ${cropCostFmt(budget)}</span></div><p>Top ${scored.length} options ranked from the details you entered. Fit scores are heuristic rankings, not probabilities of success.</p></div><div class="result-stack">${cards}</div><div class="shortlist-actions"><button class="outline-btn" id="save-recommendation" type="button">Save shortlist on this device</button><button class="outline-btn" id="print-recommendation" type="button">Print / Save as PDF</button></div><p class="result-disclaimer">Cost ranges are illustrative starter estimates, not current local quotes or profit guarantees. Market prices, yield, seed availability and crop suitability vary by district, variety and season. Confirm with current local agriculture advice and a soil test.</p>`;
  $('#recommend-results').innerHTML=html;
  $('#save-recommendation')?.addEventListener('click',async()=>{const record={date:new Date().toISOString(),location:loc,inputs:d,shortlist:scored.map(c=>({crop:c.crop,score:c.score,cost:[c.lowTotal,c.highTotal]}))};const key='agropilot-crop-shortlists-v1';let old=[];try{old=JSON.parse(localStorage.getItem(key)||'[]')}catch{};localStorage.setItem(key,JSON.stringify([record,...old].slice(0,10)));const synced=await backendPost('/api/shortlists',record);toast(synced?'Shortlist saved locally and to backend':'Shortlist saved on this device')});
  $('#print-recommendation')?.addEventListener('click',()=>window.print());
  $('#recommend-results').scrollIntoView({behavior:'smooth',block:'start'});
});
$('#diagnose-form').addEventListener('submit',e=>{
  e.preventDefault();
  const d=formObject(e.currentTarget),sym=$$('input[name="symptoms"]:checked').map(x=>x.value);
  const has=(x)=>sym.includes(x), causes=[];
  const add=(key,title,why,evidence,checks,urgency='Monitor')=>causes.push({key,title,why,evidence,checks,urgency,score:0});
  if(d.moisture==='low'||d.irrigation==='long_ago'||(d.leaf_color==='wilting'&&d.moisture!=='high')) add('dry','Water stress (too little available water)','Dry soil, recent lack of irrigation or wilting can fit water stress, but wilting alone is not proof.',['Soil moisture: '+d.moisture,'Recent irrigation: '+d.irrigation,'Leaf condition: '+d.leaf_color],['Check moisture in the active root zone at several points','Compare affected plants with healthy plants','Check irrigation coverage and crop growth stage'],'High');
  if(d.moisture==='high'||d.recent_rain==='yes'||d.irrigation==='recent'||d.root_condition==='dark_soft') add('wet','Excess water / drainage or root-zone stress','Wet soil, recent rain or dark/soft roots can be consistent with waterlogging or root problems; inspect before watering again.',['Soil moisture: '+d.moisture,'Recent rain: '+d.recent_rain,'Root condition: '+d.root_condition],['Look for standing water and blocked drainage','Inspect roots on a small number of affected plants','Do not add water until root-zone moisture is checked'],'High');
  if(d.leaf_color==='yellow'||has('yellow leaves')||d.leaf_color==='brown'||has('stunted growth')) add('nutrient','Nutrient imbalance or uptake problem','Yellowing, browning or slow growth can be related to nutrients, pH, root stress, salinity or disease; appearance alone cannot identify a specific deficiency.',['Leaf colour: '+d.leaf_color,'Fertilizer history: '+d.fertilizer,'Crop stage: '+d.growth_stage],['Check whether symptoms appear on older or newer leaves','Review fertilizer history and irrigation quality','Use a soil test before applying a nutrient or changing pH'],'Monitor');
  if(d.leaf_color==='brown'||has('brown spots')) add('disease','Possible leaf disease or environmental injury','Spots and dry edges have several possible causes, including disease, heat, spray injury and nutrient or water stress.',['Brown/black spots selected: '+has('brown spots'),'Affected spread: '+d.spread],['Photograph both sides of several leaves in natural light','Check whether spots are spreading and whether stems are affected','Ask a local agriculture officer or plant clinic to confirm before treatment'],'High');
  if(has('holes in leaves')||d.pest_signs==='yes') add('pest','Possible insect or other pest damage','Leaf holes plus visible insects, larvae, webbing or droppings increase suspicion of pest damage, but the pest still needs identification.',['Pest signs: '+d.pest_signs,'Holes in leaves selected: '+has('holes in leaves')],['Inspect leaf undersides and new growth early in the day','Look for larvae, eggs, webbing and fresh droppings','Use local integrated-pest-management guidance after identifying the pest'],'High');
  if(d.root_condition==='dark_soft'||d.root_condition==='dry_damaged'||has('wilting')||d.leaf_color==='wilting') add('root','Root or stem stress needs inspection','Wilting with root/stem changes can indicate root damage, rot or water stress. These causes cannot be distinguished from this form alone.',['Root condition: '+d.root_condition,'Leaf condition: '+d.leaf_color],['Inspect roots and stem base on a few affected plants','Compare with a healthy plant from the same field','Seek expert review if damage is spreading or plants collapse'],'High');
  if(!causes.length) add('unknown','Not enough evidence yet','The current observations do not point strongly to one cause. Avoid guessing or applying a treatment.',['No strong symptom pattern selected'],['Select all visible symptoms','Record when the issue started and whether it is spreading','Check moisture, roots, pests and recent weather']);
  // Transparent heuristic ranking, not a trained model or calibrated probability.
  causes.forEach(c=>{
    if(c.key==='dry'){if(d.moisture==='low')c.score+=3;if(d.irrigation==='long_ago')c.score+=2;if(d.leaf_color==='wilting'||has('wilting'))c.score+=2;if(d.recent_rain==='yes')c.score-=1}
    if(c.key==='wet'){if(d.moisture==='high')c.score+=3;if(d.recent_rain==='yes')c.score+=1;if(d.irrigation==='recent')c.score+=1;if(d.root_condition==='dark_soft')c.score+=2}
    if(c.key==='nutrient'){if(d.leaf_color==='yellow'||has('yellow leaves'))c.score+=2;if(has('stunted growth'))c.score+=1;if(d.fertilizer==='no')c.score+=1}
    if(c.key==='disease'){if(has('brown spots'))c.score+=2;if(d.spread==='many')c.score+=1}
    if(c.key==='pest'){if(has('holes in leaves'))c.score+=2;if(d.pest_signs==='yes')c.score+=3}
    if(c.key==='root'){if(d.root_condition==='dark_soft'||d.root_condition==='dry_damaged')c.score+=3;if(has('wilting'))c.score+=1}
    if(d.spread==='many'&&['disease','wet','root'].includes(c.key))c.score+=1;
  });
  causes.sort((a,b)=>b.score-a.score);
  const ranked=causes.map((c,i)=>`<div class="finding-card"><div class="finding-top"><span class="finding-number">0${i+1}</span><span class="confidence">${i===0&&c.score>=4?'Higher clue match':'Possible cause'}</span></div><h4>${esc(c.title)}</h4><p>${esc(c.why)}</p><b class="next-label">Why this is being considered</b><ul>${c.evidence.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><b class="next-label">Recommended next checks</b><ul>${c.checks.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>${c.urgency==='High'?'<p class="result-disclaimer">Priority: inspect soon, especially if damage is spreading.</p>':''}</div>`).join('');
  const spreadNote=d.spread==='many'?'Many plants are affected: compare multiple areas and contact a local agricultural expert promptly if the problem is spreading.':d.spread==='edge'?'Damage near field edges can be related to field-edge pests, spray drift or local conditions; compare with the field centre.':'Only a few plants are affected: mark them and inspect nearby plants for changes.';
  const farmLocation=[d.village,d.district,d.state].filter(Boolean).join(', ');
  const farmerSummary=(d.farmer_name||farmLocation||d.crop_variety||d.affected_area)?`<div class="farm-detail-summary"><b>Submitted farm details</b><p>${d.farmer_name?`Farmer: ${esc(d.farmer_name)} · `:''}Crop: ${esc(d.crop)}${d.crop_variety?` (${esc(d.crop_variety)})`:''}${farmLocation?` · Location: ${esc(farmLocation)}`:''}${d.affected_area?` · Affected area: ${esc(d.affected_area)} acres`:''}${d.planting_date?` · Planting date: ${esc(d.planting_date)}`:''}</p><small>Details are saved in this browser on this device.</small></div>`:'';
  $('#diagnose-results').innerHTML=`<div class="result-stack">${farmerSummary}<div class="notice"><span>ⓘ</span><p><b>Preliminary triage for ${esc(d.crop)}</b><br>${esc(spreadNote)} These are ranked clues from your answers, not calibrated confidence scores or a confirmed diagnosis.</p></div>${ranked}<p class="result-disclaimer">Image AI runs separately when a trained TensorFlow.js model is installed in models/crop-doctor/. If the model is not installed, this screen provides symptom-based triage only. Do not apply pesticides or fertilizers based only on this result; confirm disease or nutrient issues with a local agriculture officer, KVK or soil test.</p></div>`;
  const triageRecord={crop:d.crop,location:farmLocation,observations:d,symptoms:sym,leadingClue:causes[0]?.title||'More observations needed',createdAt:new Date().toISOString()};backendPost('/api/data/cropScans',triageRecord);activities=[{task:`Crop health triage: ${d.crop}`,farm:'User-submitted observations',priority:causes[0]?.urgency||'Medium',reason:`Leading clue: ${causes[0]?.title||'More observations needed'}. Follow-up: ${spreadNote}`,created_at:new Date().toLocaleString()},...activities].slice(0,20);save();loadActivity();toast('Crop triage complete');
});

// Advanced crop-health toolkit: transparent rules, photo comparison, reports and history.
const healthReportKey='agropilot-health-reports-v1';
let healthReports=read(healthReportKey,[]);
function healthPhotoData(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error('Choose a JPEG, PNG, or WebP photo.'));if(file.size>4*1024*1024)return reject(new Error('Each photo must be 4 MB or smaller.'));const reader=new FileReader();reader.onload=()=>resolve({dataUrl:reader.result,name:file.name,type:file.type,size:file.size});reader.onerror=()=>reject(new Error('Could not read selected photo.'));reader.readAsDataURL(file)})}
function showHealthPhotoCompare(){const before=$('#health-before-photo')?.files?.[0],after=$('#health-after-photo')?.files?.[0],host=$('#health-photo-compare');if(!host)return;const parts=[];if(before)parts.push(`<div><b>Before</b><img alt="Before crop condition" src="${URL.createObjectURL(before)}"></div>`);if(after)parts.push(`<div><b>Current</b><img alt="Current crop condition" src="${URL.createObjectURL(after)}"></div>`);host.innerHTML=parts.length?parts.join('')+'<small>Visual comparison only; lighting and angle can affect appearance.</small>':'<p class="field-help">No comparison photos selected.</p>'}
$('#health-before-photo')?.addEventListener('change',showHealthPhotoCompare);$('#health-after-photo')?.addEventListener('change',showHealthPhotoCompare);
function makeHealthAssessment(d){let score=100,findings=[],actions=[];const affected=Number(d.affectedPercent||0),ph=d.ph===''?null:Number(d.ph),humidity=d.humidity===''?null:Number(d.humidity),temp=d.temperature===''?null:Number(d.temperature);
 if(d.severity==='mild'){score-=8;findings.push('Mild symptom severity selected.')}else if(d.severity==='moderate'){score-=20;findings.push('Moderate symptoms selected; monitor affected plants closely.')}else{score-=35;findings.push('Severe symptoms selected; arrange prompt local expert inspection.');actions.push('Contact a local agriculture officer/KVK or plant clinic promptly, especially if the damage is spreading.');}
 if(affected>=50){score-=25;findings.push(`${affected}% of plants reported affected: widespread field scouting is important.`);actions.push('Inspect multiple zones and compare affected plants with a healthy patch.')}else if(affected>=20){score-=12;findings.push(`${affected}% affected: check whether symptoms are spreading.`)}
 if(d.waterStress==='dry'){score-=15;findings.push('Dry soil/wilting may fit water stress; check moisture at root depth.');actions.push('Check root-zone moisture, irrigation coverage and crop stage before watering.')}if(d.waterStress==='wet'){score-=15;findings.push('Wet soil/standing water may indicate drainage or root-zone stress.');actions.push('Inspect drainage and roots; do not add water until field conditions are checked.');}
 if(d.nitrogen==='low'||d.phosphorus==='low'||d.potassium==='low'){score-=8;findings.push('A low nutrient status was entered from a soil report; interpret it against crop and growth stage.');actions.push('Use the actual lab report and crop-specific local recommendations before applying fertilizer.');}
 if(d.nitrogen==='unknown'||d.phosphorus==='unknown'||d.potassium==='unknown'){findings.push('One or more NPK values are unknown; no nutrient deficiency can be confirmed from this form.');actions.push('Consider a recognised soil test before changing fertilizer or soil amendments.');}
 if(ph!==null&&(ph<5.5||ph>8)){score-=8;findings.push(`Entered pH ${ph} may need crop-specific interpretation and lab confirmation.`);actions.push('Confirm pH and salinity/EC with a soil-testing lab before applying amendments.');}
 if(d.pest==='yes'){score-=10;findings.push('Visible pest evidence reported; inspect both sides of leaves and stems.');actions.push('Photograph the pest and damage; confirm identification before using crop-protection products.');}
 if(humidity!==null&&humidity>=80&&d.rain==='heavy'){score-=8;findings.push('High humidity plus heavy recent rain can favour some crop diseases, depending on crop and pathogen; this is a weather-linked risk clue, not a forecast or diagnosis.');actions.push('Scout leaves and stems after rain and follow local crop-specific disease advisories.');}
 if(temp!==null&&(temp<5||temp>38)){findings.push(`Entered temperature ${temp}°C may stress some crops; crop and growth stage determine actual risk.`);actions.push('Check crop-specific temperature guidance and local forecast before field operations.');}
 if(d.rain==='heavy'){findings.push('Heavy recent rain reported: inspect drainage and field access.');actions.push('Check standing water and avoid field operations when conditions are unsafe.');}
 if(d.severity!=='severe'&&affected<20)actions.push('Mark a few affected plants and re-check them in 2–3 days under similar lighting.');actions.push('Take clear photos of both sides of leaves and record when symptoms started.');if(!actions.some(a=>a.toLowerCase().includes('expert'))&&affected>=20)actions.push('If symptoms continue to spread, seek a local agriculture expert’s assessment.');
 if(!findings.length)findings.push('No strong risk clues were entered. Continue regular scouting; this does not prove the crop is disease-free.');return {score:Math.max(0,Math.min(100,score)),findings,actions,inputs:d,createdAt:new Date().toISOString(),id:Date.now()}}
function renderHealthReportHistory(){const host=$('#health-report-history');if(!host)return;if(!healthReports.length){host.innerHTML='<div class="empty-state"><b>No health reports saved yet</b><p>Generate a report to build your crop health history.</p></div>';return}host.innerHTML=healthReports.slice(0,20).map((r,i)=>`<article class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(r.crop||'Crop')}</span><span class="priority ${r.assessment?.score<60?'high':r.assessment?.score<80?'medium':'low'}">Indicator ${Number(r.assessment?.score??0)}/100</span></div><h4>${esc(r.createdAt?new Date(r.createdAt).toLocaleString('en-IN'):'Saved report')}</h4><p>${esc((r.assessment?.findings||[]).slice(0,2).join(' '))}</p><button type="button" class="outline-btn" data-health-report="${i}">View report</button></article>`).join('')}
$('#advanced-health-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=formObject(e.currentTarget);if(!e.currentTarget.reportValidity())return;let before=null,after=null;try{before=await healthPhotoData($('#health-before-photo')?.files?.[0]);after=await healthPhotoData($('#health-after-photo')?.files?.[0])}catch(err){toast(err.message);return}const assessment=makeHealthAssessment(d),diagnoseCrop=$('#diagnose-form')?.elements?.crop?.value||'Not specified',record={crop:diagnoseCrop,location:[$('#diagnose-form')?.elements?.village?.value,$('#diagnose-form')?.elements?.district?.value,$('#diagnose-form')?.elements?.state?.value].filter(Boolean).join(', '),assessment,notes:d.notes||'',photos:{beforeName:before?.name||'',afterName:after?.name||''},createdAt:assessment.createdAt};
 for(const [key,photo] of [['before',before],['after',after]]){if(!photo)continue;const uploaded=await backendPost('/api/uploads',{dataUrl:photo.dataUrl,originalName:photo.name,crop:record.crop,location:record.location,photoRole:`health-${key}`});if(uploaded?.item)record.photos[`${key}Url`]=uploaded.item.url;}
 healthReports=[record,...healthReports].slice(0,50);localStorage.setItem(healthReportKey,JSON.stringify(healthReports));const synced=await backendPost('/api/data/healthReports',record);const risk=assessment.score<60?'Needs prompt review':assessment.score<80?'Monitor closely':'No major rule-based flags entered';
 $('#advanced-health-results').innerHTML=`<div class="health-report-print"><div class="health-score-card"><div><span class="welcome-kicker">RULE-BASED PLANT HEALTH INDICATOR</span><div class="health-score-number">${assessment.score}<small>/100</small></div><b>${esc(risk)}</b></div><p>Indicator only—not a disease probability or proof of healthy crop. Generated ${esc(new Date(record.createdAt).toLocaleString('en-IN'))}.</p></div><div class="health-report-grid"><section><h4>Assessment findings</h4><ul>${assessment.findings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section><h4>Personalized action plan</h4><ol>${assessment.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section></div><section class="health-report-notes"><h4>Notes & observations</h4><p>${esc(d.notes||'No extra notes entered.')}</p><p><b>Crop stage:</b> ${esc(d.stage)} · <b>Severity:</b> ${esc(d.severity)} · <b>Reported affected:</b> ${esc(d.affectedPercent)}%</p>${record.photos.beforeUrl||record.photos.afterUrl?`<p>Saved photos: ${record.photos.beforeUrl?`<a href="${esc(record.photos.beforeUrl)}" target="_blank" rel="noopener noreferrer">Before photo</a>`:''} ${record.photos.afterUrl?`<a href="${esc(record.photos.afterUrl)}" target="_blank" rel="noopener noreferrer">Current photo</a>`:''}</p>`:''}</section><div class="shortlist-actions"><button class="outline-btn" type="button" id="print-health-report">Print / Save as PDF</button><button class="outline-btn" type="button" id="save-health-recovery">Add follow-up reminder</button></div><p class="result-disclaimer">This report uses entered observations and simple rules only. It does not diagnose disease, validate nutrient deficiency, or provide pesticide dosage. Consult a qualified local expert for severe or spreading symptoms.</p></div>`;
 $('#print-health-report')?.addEventListener('click',()=>window.print());$('#save-health-recovery')?.addEventListener('click',()=>{const log={crop:record.crop,condition:'uncertain',action:'Follow up on Crop Health report',notes:`Re-check in 2–3 days. ${assessment.findings[0]||''}`,date:new Date(Date.now()+2*86400000).toLocaleDateString('en-IN')};recoveryLogs=[log,...recoveryLogs].slice(0,100);persistList(recoveryKey,recoveryLogs);renderRecovery();toast('Follow-up added to recovery tracker')});renderHealthReportHistory();toast(synced?'Health report saved and synced to backend':'Health report saved on this device');});
$('#refresh-health-reports')?.addEventListener('click',async()=>{const result=await fetch('/api/data/healthReports').then(r=>r.ok?r.json():null).catch(()=>null);if(result?.items){const seen=new Set(healthReports.map(r=>r.createdAt));healthReports=[...healthReports,...result.items.filter(r=>!seen.has(r.createdAt))].slice(0,50);localStorage.setItem(healthReportKey,JSON.stringify(healthReports));renderHealthReportHistory();toast('Health report history refreshed')}else{renderHealthReportHistory();toast('Showing this device history; start npm start for backend sync')}});
$('#health-report-history')?.addEventListener('click',e=>{const b=e.target.closest('[data-health-report]');if(!b)return;const r=healthReports[Number(b.dataset.healthReport)];if(!r)return;$('#advanced-health-results').innerHTML=`<div class="health-report-print"><div class="health-score-card"><div><span class="welcome-kicker">SAVED REPORT</span><div class="health-score-number">${Number(r.assessment?.score??0)}<small>/100</small></div></div><p>${esc(r.createdAt?new Date(r.createdAt).toLocaleString('en-IN'):'')}</p></div><h4>Findings</h4><ul>${(r.assessment?.findings||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Action plan</h4><ol>${(r.assessment?.actions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>${esc(r.notes||'No notes')}</p><button class="outline-btn" type="button" id="print-health-report">Print / Save as PDF</button><p class="result-disclaimer">Rule-based tracking only; not a confirmed diagnosis.</p></div>`;$('#print-health-report')?.addEventListener('click',()=>window.print());$('#advanced-health-results').scrollIntoView({behavior:'smooth',block:'start'})});
renderHealthReportHistory();
const weatherCodeLabel=(code)=>({0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',48:'Depositing rime fog',51:'Light drizzle',53:'Drizzle',55:'Dense drizzle',56:'Freezing drizzle',57:'Dense freezing drizzle',61:'Light rain',63:'Moderate rain',65:'Heavy rain',66:'Freezing rain',67:'Heavy freezing rain',71:'Light snow',73:'Snow',75:'Heavy snow',77:'Snow grains',80:'Light rain showers',81:'Rain showers',82:'Violent rain showers',85:'Snow showers',86:'Heavy snow showers',95:'Thunderstorm',96:'Thunderstorm with hail',99:'Severe thunderstorm with hail'})[code]||'Conditions unavailable';
function cropWeatherAdvice(crop,stage,weather,soilMoisture,waterSource){
 const c=String(crop||'Other').toLowerCase(),t=weather.current.temperature_2m,humidity=weather.current.relative_humidity_2m,rainProb=weather.daily.precipitation_probability_max?.[0]??0,rainMm=weather.daily.precipitation_sum?.[0]??0,wind=weather.current.wind_speed_10m??0,et0=weather.daily.et0_fao_evapotranspiration?.[0];
 const notes=[],actions=[];let risk='Routine monitoring';
 if(t>=38){risk='Heat watch';notes.push(`Current air temperature is ${Math.round(t)}°C; heat stress risk can rise, especially around flowering and grain/fruit filling.`);actions.push('Inspect leaf rolling/wilting and root-zone moisture during the cooler part of the day; avoid relying on temperature alone to schedule irrigation.');}
 else if(t<=5){risk='Cold watch';notes.push(`Current air temperature is ${Math.round(t)}°C; cold-sensitive crops may be affected.`);actions.push('Check crop-specific local cold/frost advisories and protect sensitive seedlings only using locally recommended methods.');}
 if(rainProb>=70||rainMm>=10){risk=risk==='Routine monitoring'?'Rain / field-access watch':risk+' + rain watch';notes.push(`Rain probability today is ${Math.round(rainProb)}% with forecast precipitation ${Number(rainMm).toFixed(1)} mm.`);actions.push('Check drainage and soil moisture before irrigation; postpone spraying if rain or wind may reduce effectiveness, following the product label and local advisory.');}
 if(wind>=25){notes.push(`Wind is around ${Math.round(wind)} km/h, which can affect spraying and field work.`);actions.push('Avoid drift-prone spraying in unsuitable wind; follow pesticide label and local extension guidance.');}
 if(humidity>=85){notes.push(`Relative humidity is high (${Math.round(humidity)}%); some diseases may be favoured depending on crop, leaf wetness and pathogen.`);actions.push('Scout leaves and stems for crop-specific symptoms, especially after rain; humidity alone does not diagnose disease.');}
 if(soilMoisture==='dry'){notes.push('Farmer-entered field observation: soil marked dry. Forecast rain is only one input.');actions.push(rainProb>=50?'Recheck root-zone moisture after expected rain before deciding on irrigation.':'Check moisture at root depth and crop stage; irrigate only if the crop-specific need and local practice support it.');}
 if(soilMoisture==='wet'){notes.push('Farmer-entered field observation: soil marked wet / waterlogged.');actions.push('Inspect standing water and drainage; avoid additional irrigation until the root zone is checked.');}
 if(stage==='Flowering'&& (t>=35||rainProb>=60||wind>=25)){notes.push('Flowering stage selected: adverse heat, rain or wind may matter more during this sensitive stage, depending on crop.');actions.push('Monitor flowering and pollination/fruit set closely and consult crop-specific extension guidance for the selected crop.');}
 if(['rice','sugarcane'].includes(c)&&soilMoisture==='dry') actions.push('For this crop, confirm its stage-specific water requirement and local irrigation method before changing the water schedule.');
 if(['tomato','potato','chickpea','mustard','wheat'].includes(c)&&rainProb>=60) actions.push('Check crop canopy, drainage and field accessibility after rain; avoid entering saturated soil if it may cause compaction.');
 if(et0!=null)notes.push(`Reference evapotranspiration (ET₀) forecast today: ${Number(et0).toFixed(1)} mm. This is atmospheric demand, not the crop’s exact irrigation requirement; crop coefficient, effective rainfall, soil and irrigation efficiency are also needed.`);
 if(!actions.length)actions.push('No strong weather alert from these thresholds. Continue normal scouting and check actual root-zone moisture before irrigation.');
 return {risk,notes:[...new Set(notes)],actions:[...new Set(actions)]};
}
async function findWeatherPlace(){const place=$('#weather-place').value.trim();if(!place){$('#weather-location-note').textContent='Enter a village, district or city first.';return}const btn=$('#weather-find-place');btn.disabled=true;btn.textContent='Searching…';try{const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(place)}&count=5&language=en&format=json`);if(!r.ok)throw Error('Location search service is unavailable');const data=await r.json();if(!data.results?.length)throw Error('No matching location found. Try district and state name.');const match=data.results.find(x=>/india/i.test(x.country||''))||data.results[0];$('#lat').value=Number(match.latitude).toFixed(4);$('#lon').value=Number(match.longitude).toFixed(4);$('#weather-place').value=[match.name,match.admin2,match.admin1,match.country].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(', ');$('#weather-location-note').textContent=`Location found: ${$('#weather-place').value}. Forecast uses approximate coordinates; confirm they match your field.`;await loadWeather()}catch(e){$('#weather-location-note').textContent=`Location search failed: ${e.message}. You can enter coordinates manually.`}finally{btn.disabled=false;btn.textContent='Find location'}}
async function loadWeather(){
 const lat=Number($('#lat').value),lon=Number($('#lon').value);if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat < -90||lat>90||lon < -180||lon>180){$('#weather-results').innerHTML='<div class="notice warning"><span>!</span><p>Enter valid latitude (-90 to 90) and longitude (-180 to 180).</p></div>';return}
 $('#weather-results').innerHTML='<div class="loading">Fetching live weather and 7-day forecast…</div>';$('#weather-status').textContent='Loading live data';
 try{
  const params=new URLSearchParams({latitude:String(lat),longitude:String(lon),timezone:'auto',forecast_days:'7',current:'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,rain,showers,weather_code,cloud_cover,wind_speed_10m,wind_gusts_10m,wind_direction_10m',hourly:'temperature_2m,relative_humidity_2m,precipitation_probability,precipitation,wind_speed_10m,weather_code',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max,uv_index_max,sunrise,sunset,et0_fao_evapotranspiration'});
  const r=await fetch(`https://api.open-meteo.com/v1/forecast?${params}`);if(!r.ok)throw Error(`Weather service returned ${r.status}`);const w=await r.json();if(!w.current||!w.daily||!w.hourly)throw Error('Weather service returned incomplete data');
  currentWeather={live:true,rain_probability:w.daily.precipitation_probability_max?.[0]??0,updatedAt:new Date().toISOString()};$('#weather-status').textContent='Live forecast';
  const c=w.current,d=w.daily,h=w.hourly,crop=$('#weather-crop').value,stage=$('#weather-stage').value,soil=$('#weather-soil-moisture').value,water=$('#weather-water').value,advice=cropWeatherAdvice(crop,stage,w,soil,water);
  const dailyCards=d.time.map((date,i)=>`<article class="forecast-card"><small>${new Date(date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})}</small><span class="forecast-icon">${(d.weather_code[i]===0?'☀':([1,2,3].includes(d.weather_code[i])?'⛅':([45,48].includes(d.weather_code[i])?'🌫':'🌧')))}</span><b>${Math.round(d.temperature_2m_max[i])}° / ${Math.round(d.temperature_2m_min[i])}°C</b><span class="rain-label">☂ ${d.precipitation_probability_max[i]??'—'}% · ${Number(d.precipitation_sum[i]||0).toFixed(1)} mm</span><small>Wind max ${Math.round(d.wind_speed_10m_max[i]||0)} km/h · UV ${d.uv_index_max?.[i]??'—'}</small><small>${weatherCodeLabel(d.weather_code[i])}</small></article>`).join('');
  const now=new Date();let start=h.time.findIndex(t=>new Date(t)>=now);if(start<0)start=0;const hourlyCards=h.time.slice(start,start+24).filter((_,i)=>i%3===0).map((time,j)=>{const i=start+j*3;return `<div class="hourly-weather-card"><small>${new Date(time).toLocaleTimeString('en-IN',{hour:'numeric',hour12:true})}</small><b>${Math.round(h.temperature_2m[i])}°C</b><span>${weatherCodeLabel(h.weather_code[i])}</span><small>Rain ${h.precipitation_probability[i]??'—'}% · ${Number(h.precipitation[i]||0).toFixed(1)} mm</small><small>Wind ${Math.round(h.wind_speed_10m[i]||0)} km/h</small></div>`}).join('');
  const metrics=[['Feels like',`${Math.round(c.apparent_temperature)}°C`],['Humidity',`${c.relative_humidity_2m}%`],['Rain now',`${Number(c.precipitation||0).toFixed(1)} mm`],['Wind',`${Math.round(c.wind_speed_10m||0)} km/h`],['Wind gust',`${Math.round(c.wind_gusts_10m||0)} km/h`],['Cloud cover',`${c.cloud_cover}%`],['Sunrise',d.sunrise?.[0]?new Date(d.sunrise[0]).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}):'—'],['Sunset',d.sunset?.[0]?new Date(d.sunset[0]).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}):'—'],['ET₀ today',d.et0_fao_evapotranspiration?.[0]!=null?`${Number(d.et0_fao_evapotranspiration[0]).toFixed(1)} mm`:'—']];
  $('#weather-results').innerHTML=`<div class="weather-hero"><div class="weather-current"><div><span class="weather-eyebrow">LIVE CONDITIONS · OPEN-METEO</span><div class="temperature">${Math.round(c.temperature_2m)}<sup>°C</sup></div><p>${weatherCodeLabel(c.weather_code)} · ${new Date(c.time).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}</p><div class="weather-mini">Humidity <b>${c.relative_humidity_2m}%</b> &nbsp; Precipitation <b>${Number(c.precipitation||0).toFixed(1)} mm</b></div></div><div class="weather-sun">${c.is_day?'☀':'🌙'}</div></div><div class="weather-advice"><span>✦ CROP-SPECIFIC WEATHER WATCH</span><h4>${esc(advice.risk)}</h4><p>${esc(advice.notes[0]||'No major threshold-based weather signal detected.')}</p><small>Crop: ${esc(crop)} · Stage: ${esc(stage)}</small></div></div><div class="weather-metric-grid">${metrics.map(m=>`<div class="weather-metric"><small>${m[0]}</small><b>${m[1]}</b></div>`).join('')}</div><section class="weather-subpanel"><div class="panel-heading"><div><h3>Crop & field action plan</h3><p>Based on current weather thresholds and your selected field observations.</p></div></div><div class="weather-advisory-list">${advice.notes.map(n=>`<div class="weather-advisory-note"><span>i</span><p>${esc(n)}</p></div>`).join('')}${advice.actions.map(a=>`<div class="weather-action-note"><span>✓</span><p>${esc(a)}</p></div>`).join('')}</div><p class="result-disclaimer">This is a rule-based advisory, not a crop-specific validated disease model or an exact irrigation prescription. ET₀ is reference evapotranspiration, not direct crop water use.</p></section><section class="weather-subpanel"><div class="panel-heading"><div><h3>Next 24 hours</h3><p>Hourly forecast samples, shown every three hours.</p></div></div><div class="hourly-weather-grid">${hourlyCards||'<p class="muted">Hourly data unavailable.</p>'}</div></section><section class="weather-subpanel"><div class="panel-heading"><div><h3>7-day forecast</h3><p>Temperature, rain probability, precipitation, wind and UV index.</p></div></div><div class="forecast-grid weather-seven-day">${dailyCards}</div></section><p class="result-disclaimer">Source: Open-Meteo forecast API. Forecast uncertainty increases with lead time; the API does not measure your exact field. Last fetched ${new Date().toLocaleString('en-IN')}.</p>`;
  if($('#rain-prob'))$('#rain-prob').value=String(Math.round(currentWeather.rain_probability));
 }catch(e){currentWeather={live:false,rain_probability:null};$('#weather-status').textContent='Live data unavailable';$('#weather-results').innerHTML=`<div class="notice warning"><span>!</span><p><b>Live weather could not be loaded.</b> ${esc(e.message)}. No sample values are shown as real weather. Check your internet connection or try again later; verify conditions with a trusted local weather source before making crop decisions.</p></div>`}
}
