$('#clear-chat')?.addEventListener('click',()=>{chatHistory=[];try{localStorage.removeItem(chatHistoryKey)}catch{};$('#chat-messages').innerHTML='<div class="chat-bubble bot">Chat cleared on this device. Ask a new farming question in Hindi or English whenever you are ready.<small>Agri Assistant · general decision support</small></div>';toast('Local chat history cleared')});
