// Extended hackathon demo: explainable decisions, scenario calculator, field zones and voice input.
Object.assign(titles,{decision:'Autonomous decision engine',impact:'Water & profit simulator',fieldmap:'Field health zones'});
const originalGo=go;
go=function(view){originalGo(view);};

let latestDecisionRun = null;
$('#decision-form')?.addEventListener('submit',async e=>{
  e.preventDefault();
  const form=e.currentTarget, d=formObject(form), rainField=form.elements.rain;
  const rainText=String(d.rain??'').trim(), rain=Number(rainText);
  if(!rainText||!Number.isFinite(rain)||rain<0||rain>100){rainField.setCustomValidity('Enter a valid rain probability from 0 to 100.');rainField.reportValidity();rainField.setCustomValidity('');return}
  const allowedMoisture=['low','medium','high'];
  const allowedCondition=['normal','yellow','wilting','spots','stunted'];
  if(!allowedMoisture.includes(d.moisture)||!allowedCondition.includes(d.condition)){toast('Please check all field observations and try again.');return}
  const crop=String(d.crop||'Crop'), stage=String(d.stage||'growth stage'), moisture=d.moisture, condition=d.condition;
  const items=[];
  const add=(p,title,why,category='Field check')=>items.push({p,title,why,category});
  if(moisture==='high') add('High','Inspect drainage before adding water','Soil is marked wet. Check standing water, drainage outlets and root-zone condition; do not irrigate until moisture is reassessed.','Water management');
  else if(moisture==='low'&&rain>=50) add('High','Verify root-zone moisture before irrigation',`Soil is marked dry but rain probability is ${rain}%. Check the forecast timing and actual moisture at root depth before deciding to water.`,'Water management');
  else if(moisture==='low') add('High','Check whether irrigation is needed','Soil is marked dry and rain probability is below 50%. Confirm moisture at root depth, soil type and crop stage before irrigating.','Water management');
  else if(moisture==='medium'&&rain>=70) add('Medium','Recheck field after likely rain',`Rain probability is ${rain}%. Confirm actual rainfall and root-zone moisture before irrigation or machinery entry.`,'Weather');
  else if(moisture==='medium') add('Medium','Continue moisture monitoring','Moisture is marked moderate. Recheck at root depth and avoid relying on a fixed schedule alone.','Water management');
  if(condition==='yellow') add('High','Investigate yellowing before treatment','Possible causes include nutrient imbalance, waterlogging, pests or disease. Compare affected and healthy plants, inspect roots/drainage, and use a soil test where possible before applying nutrients.','Crop health');
  else if(condition==='wilting') add('High','Inspect wilting plants and soil','Wilting can result from dry soil, root stress, heat or disease. Check root-zone moisture and roots first; do not assume the crop simply needs more water.','Crop health');
  else if(condition==='spots') add('Medium','Scout leaf spots or damage','Inspect both sides of leaves and several plants. Record whether symptoms are spreading and seek crop-specific confirmation before any pesticide use.','Crop health');
  else if(condition==='stunted') add('Medium','Compare growth and root conditions','Compare affected plants with healthy plants; review moisture, root health, crop stage and soil-test results before changing fertilizer.','Crop health');
  if(rain>=70 && moisture!=='high') add('Medium','Prepare for possible rainfall','Check the local forecast, field drainage and safe access. Reassess after rain; probability is not a guarantee that rain will occur.','Weather');
  if(stage.toLowerCase().includes('flower')||stage.toLowerCase().includes('grain')||stage.toLowerCase().includes('fruit')) add('Medium','Inspect sensitive growth-stage conditions',`For ${crop} at ${stage}, monitor water stress and weather exposure closely. Exact thresholds depend on variety and local agronomy.`,'Growth stage');
  if(condition==='normal') add('Low','Continue routine crop scouting',`Inspect ${crop} leaves, stems and field moisture at the ${stage.toLowerCase()} stage; record any new symptoms.`,'Monitoring');
  add('Low','Record the next observation',`Save the date, crop (${crop}), stage (${stage}) and any changes after the selected checks. Reassess before changing irrigation or inputs.`,'Record keeping');
  const priorityRank={High:0,Medium:1,Low:2};items.sort((a,b)=>priorityRank[a.p]-priorityRank[b.p]);
  const createdAt=new Date().toISOString();
  latestDecisionRun={id:`decision-${Date.now()}`,crop,stage,moisture,rain,condition,createdAt,items:items.map(x=>({...x,status:'suggested'})),source:'rule-based-decision-engine'};
  const host=$('#decision-results');
  host.innerHTML=`<div class="decision-list"><div class="plan-summary"><div><span>DECISION REVIEW</span><b>${items.length} suggested actions</b><small>${esc(crop)} · ${esc(stage)} · Generated ${new Date(createdAt).toLocaleString('en-IN')}</small></div><div class="plan-total-icon">✦</div></div>${items.map((x,i)=>`<article class="decision-card"><div class="decision-card-top"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="priority ${x.p.toLowerCase()}">${x.p} priority</span></div><small class="muted">${esc(x.category)}</small><h4>${esc(x.title)}</h4><p>${esc(x.why)}</p><button type="button" class="outline-btn log-decision" data-task="${esc(x.title)}" data-reason="${esc(x.why)}" data-priority="${esc(x.p)}" data-category="${esc(x.category)}">Log for follow-up</button></article>`).join('')}<p class="result-disclaimer">Explainable rule-based guidance from your entered observations—not live sensor readings, a validated crop model, or expert diagnosis. Rain probability is not a guarantee. Review actions before acting.</p></div>`;
  const saved=await backendPost('/api/data/decisions',latestDecisionRun);
  toast(saved?'Decision results generated and saved to backend':'Decision results generated; backend unavailable, results are shown for this session');
});
