let lastYieldRiskRows=[];
$('#yield-form')?.addEventListener('submit',e=>{
  e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;
  const d=formObject(form),area=Number(d.area),base=Number(d.yield),price=Number(d.price),cost=Number(d.cost);
  if(![area,base,price,cost].every(Number.isFinite)||area<=0||area>100000||base<0||base>100000||price<0||price>100000000||cost<0||cost>100000000000){toast('Check inputs: values must be valid and within reasonable limits');return}
  const assumptions={low:{downYield:.95,upYield:1.05,downPrice:.95,upPrice:1.05,costOverrun:.05,label:'Lower risk'},medium:{downYield:.85,upYield:1.08,downPrice:.90,upPrice:1.05,costOverrun:.10,label:'Moderate risk'},high:{downYield:.70,upYield:1.10,downPrice:.80,upPrice:1.08,costOverrun:.20,label:'Higher risk'}};
  const a=assumptions[d.risk]||assumptions.medium;
  const specs=[{key:'downside',name:'Downside / stress',yieldFactor:a.downYield,priceFactor:a.downPrice,costFactor:1+a.costOverrun},{key:'base',name:'Baseline estimate',yieldFactor:1,priceFactor:1,costFactor:1},{key:'upside',name:'Upside illustration',yieldFactor:a.upYield,priceFactor:a.upPrice,costFactor:1}];
  lastYieldRiskRows=specs.map(x=>{const yieldPerAcre=base*x.yieldFactor,production=yieldPerAcre*area,scenarioPrice=price*x.priceFactor,revenue=production*scenarioPrice,scenarioCost=cost*x.costFactor,net=revenue-scenarioCost,breakEvenPrice=production>0?scenarioCost/production:null,breakEvenYieldPerAcre=price>0?scenarioCost/(price*area):null;return {...x,yieldPerAcre,production,scenarioPrice,revenue,scenarioCost,net,breakEvenPrice,breakEvenYieldPerAcre}});
  const money=n=>'₹'+Math.round(n).toLocaleString('en-IN');
  const cards=lastYieldRiskRows.map(r=>`<article class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(r.name)}</span><span class="priority ${r.net>=0?'low':'high'}">${r.net>=0?'Positive estimate':'Loss scenario'}</span></div><h4>${esc(d.crop)} · ${r.production.toFixed(1)} quintals total</h4><div class="impact-metrics"><div><small>Yield / acre</small><b>${r.yieldPerAcre.toFixed(2)} q</b></div><div><small>Assumed price</small><b>${money(r.scenarioPrice)} / q</b></div><div><small>Gross revenue</small><b>${money(r.revenue)}</b></div><div><small>Estimated cost</small><b>${money(r.scenarioCost)}</b></div><div class="${r.net>=0?'positive':'negative'}"><small>Net return</small><b>${money(r.net)}</b></div><div><small>Break-even price</small><b>${r.breakEvenPrice===null?'N/A':money(r.breakEvenPrice)+' / q'}</b></div></div><p class="result-disclaimer">${r.breakEvenYieldPerAcre===null?'Break-even yield cannot be calculated when price is zero.':`Break-even yield at this price: ${r.breakEvenYieldPerAcre.toFixed(2)} quintals/acre.`}</p></article>`).join('');
  const downside=lastYieldRiskRows[0],baseRow=lastYieldRiskRows[1];
  $('#yield-results').innerHTML=`<div class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(a.label)} assumptions</span><span class="confidence">Illustrative only</span></div><h4>Risk summary</h4><p>Stress case assumes ${(100*(1-a.downYield)).toFixed(0)}% lower yield, ${(100*(1-a.downPrice)).toFixed(0)}% lower selling price and ${(100*a.costOverrun).toFixed(0)}% higher costs. These are editable-by-code scenario assumptions, not measured odds or a local forecast.</p><div class="impact-metrics"><div><small>Baseline net return</small><b class="${baseRow.net>=0?'positive':'negative'}">${money(baseRow.net)}</b></div><div><small>Downside net return</small><b class="${downside.net>=0?'positive':'negative'}">${money(downside.net)}</b></div><div><small>Downside change vs baseline</small><b class="${downside.net-baseRow.net>=0?'positive':'negative'}">${money(downside.net-baseRow.net)}</b></div><div><small>Estimated break-even yield</small><b>${baseRow.breakEvenYieldPerAcre===null?'N/A':baseRow.breakEvenYieldPerAcre.toFixed(2)+' q/acre'}</b></div></div></div><div class="result-stack">${cards}</div><div class="shortlist-actions"><button class="outline-btn" id="export-yield-risk" type="button">Export scenarios as CSV</button><button class="outline-btn" id="print-yield-risk" type="button">Print / Save as PDF</button></div><p class="result-disclaimer">Calculations use only your entered baseline yield, price and total cost plus the displayed scenario assumptions. They exclude unentered costs, taxes, loan interest, quality deductions and market/season variation. No scenario is a guarantee or trained AI forecast.</p>`;
  $('#export-yield-risk')?.addEventListener('click',()=>{if(!lastYieldRiskRows.length)return;const cols=['scenario','crop','area_acres','baseline_yield_quintals_per_acre','scenario_yield_quintals_per_acre','total_production_quintals','scenario_price_per_quintal','gross_revenue','estimated_cost','net_return','break_even_price_per_quintal'];const csvCell=v=>{let x=String(v??'');if(/^[=+@\-\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'};const csv=[cols.join(','),...lastYieldRiskRows.map(r=>[r.name,d.crop,area,base,r.yieldPerAcre,r.production,r.scenarioPrice,r.revenue,r.scenarioCost,r.net,r.breakEvenPrice??''].map(csvCell).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='agropilot-yield-risk-scenarios.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Scenario CSV exported')});
  $('#print-yield-risk')?.addEventListener('click',()=>window.print());toast('Yield and risk scenarios calculated');
});
function localDateISO(date=new Date()){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
function calendarDueState(task){const today=localDateISO();if(task.done)return 'completed';if(!task.date)return 'unknown';if(task.date<today)return 'overdue';if(task.date===today)return 'today';return 'upcoming'}
function renderCalendar(){const host=$('#calendar-results');if(!host)return;const today=localDateISO();const total=calendarTasks.length,completed=calendarTasks.filter(t=>t.done).length,needs=calendarTasks.filter(t=>!t.done&&t.date<=today).length;const summary=$('#calendar-summary');if(summary)summary.innerHTML=`<div><small>Total tasks</small><b>${total}</b></div><div><small>Due / overdue</small><b>${needs}</b></div><div><small>Completed</small><b>${completed}</b></div>`;const filter=$('#calendar-filter')?.value||'all',crop=$('#calendar-crop-filter')?.value||'all',query=($('#calendar-search')?.value||'').trim().toLowerCase();const rows=calendarTasks.filter(t=>{const state=calendarDueState(t);if(filter==='open'&&t.done)return false;if(filter==='overdue'&&state!=='overdue')return false;if(filter==='today'&&state!=='today')return false;if(filter==='completed'&&!t.done)return false;if(crop!=='all'&&t.crop!==crop)return false;if(query&&!`${t.task||''} ${t.notes||''} ${t.category||''} ${t.crop||''}`.toLowerCase().includes(query))return false;return true}).sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'').localeCompare(b.date||'')||(a.priority==='High'?-1:1));if(!rows.length){host.innerHTML=`<div class="empty-state"><b>${calendarTasks.length?'No tasks match these filters':'No tasks scheduled'}</b><p>${calendarTasks.length?'Change the filters or search term.':'Add a task to get started.'}</p></div>`;return}host.innerHTML=rows.map(t=>{const state=calendarDueState(t),status=state==='overdue'?'Overdue':state==='today'?'Due today':state==='completed'?'Completed':'Upcoming';const taskId=String(t.id);return `<div class="decision-card ${t.done?'calendar-task-complete':''}"><div class="decision-card-top"><span class="status-tag">${esc(t.crop||'Other')} · ${esc(t.category||'Farm task')}</span><span class="priority ${esc((t.priority||'Medium').toLowerCase())}">${esc(t.priority||'Medium')}</span></div><h4>${esc(t.task||'Untitled task')}</h4><p>Due: <b>${esc(t.date||'Date not set')}</b> · <b class="calendar-state ${state}">${status}</b></p>${t.notes?`<p>${esc(t.notes)}</p>`:''}<div class="calendar-task-actions"><button class="outline-btn" type="button" data-task-toggle="${esc(taskId)}">${t.done?'Reopen task':'Mark complete'}</button><button class="outline-btn" type="button" data-task-delete="${esc(taskId)}">Delete</button></div></div>`}).join('')}
