$('#calendar-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=formObject(form);if(!d.task?.trim()||!d.date){toast('Enter a task and due date');return}if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)){toast('Choose a valid due date');return}calendarTasks.push({...d,task:d.task.trim(),notes:(d.notes||'').trim(),done:false,createdAt:new Date().toISOString(),completedAt:null,id:`task-${Date.now()}-${Math.random().toString(36).slice(2,7)}`});saveCalendar();form.reset();$('#calendar-form [name="date"]').value=localDateISO();toast('Task added to calendar')});
$('#calendar-results')?.addEventListener('click',e=>{const toggle=e.target.closest('[data-task-toggle]'),del=e.target.closest('[data-task-delete]');if(toggle){const task=calendarTasks.find(t=>String(t.id)===toggle.dataset.taskToggle);if(!task)return;task.done=!task.done;task.completedAt=task.done?new Date().toISOString():null;saveCalendar();toast(task.done?'Task marked complete':'Task reopened')}else if(del){const task=calendarTasks.find(t=>String(t.id)===del.dataset.taskDelete);if(!task)return;if(!window.confirm(`Delete task “${task.task}”?`))return;calendarTasks=calendarTasks.filter(t=>String(t.id)!==del.dataset.taskDelete);saveCalendar();toast('Task deleted')}});
