$('#export-calendar')?.addEventListener('click',()=>{if(!calendarTasks.length){toast('No tasks to export');return}const cols=['task','crop','category','date','priority','done','completedAt','notes'];const cell=v=>{let x=String(v??'');if(/^[=+@\-\t\r]/.test(x))x="'"+x;return `"${x.replace(/"/g,'""')}"`};const csv=[cols.join(','),...calendarTasks.map(t=>cols.map(k=>cell(t[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='agropilot-farm-calendar.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Calendar CSV exported')});
